/**
 * @threadspec
 * threads: [TEMPLATE_LOADING, VALIDATION]
 * expects: { template: 'object', size: '>0' }
 * produces: { validated: 'boolean' }
 * intersects: [PARSING at parse(), ERROR_HANDLING at catch()]
 */
async function validateTemplate(template: any): Promise<boolean> {
    // Entry checkpoint
    logger.checkpoint('TEMPLATE_LOADING', 'validateTemplate.entry', {
        threads: ['TEMPLATE_LOADING', 'VALIDATION'],
        input: { size: template?.length, type: typeof template },
        expects: { template: 'object', size: '>0' }
    });

    try {
        // Implementation
        const result = await this.validate(template);

        // Exit checkpoint
        logger.checkpoint('TEMPLATE_LOADING', 'validateTemplate.exit', {
            threads: ['TEMPLATE_LOADING', 'VALIDATION'],
            output: { validated: result },
            duration: performance.now() - startTime
        });

        return result;
    } catch (error) {
        // Error intersection
        logger.checkpoint('ERROR_HANDLING', 'validateTemplate.error', {
            threads: ['TEMPLATE_LOADING', 'VALIDATION', 'ERROR_HANDLING'],
            error: error.message,
            state: { template: template?.id }
        });
        throw error;
    }
}

