// Add to existing Logger class
export class PathwayLogger extends Logger {
    private activeThreads: Set<string> = new Set();
    private threadControl: ThreadControl;

    checkpoint(thread: string | string[], context: string, data?: any): void {
        const threads = Array.isArray(thread) ? thread : [thread];

        // Only log if at least one thread is active
        const active = threads.filter(t => this.activeThreads.has(t));
        if (active.length === 0 && !this.threadControl.isLoggingAll()) return;

        const checkpoint = {
            timestamp: Date.now(),
            threads: active,
            context,
            data,
            callstack: this.captureCallstack(1),
            correlationId: this.getCorrelationId()
        };

        // Write to pathway log file
        this.writePathwayLog(checkpoint);

        // Also log to console in debug mode
        if (this.level <= LogLevel.DEBUG) {
            this.debug(LogCategory.PATHWAY, 
                `[${active.join(',')}] ${context}`, 
                context, 
                data
            );
        }
    }

    private writePathwayLog(checkpoint: any): void {
        // Write to .pathway-logs/session-{timestamp}.jsonl
        // JSON Lines format for streaming processing
        fs.appendFileSync(
            this.getPathwayLogFile(),
            JSON.stringify(checkpoint) + '\n'
        );
    }
}

