export class ThreadControl {
    private config: ThreadConfig;
    private activeThreads: Set<string> = new Set();

    // Load from .pathway-config.json or VSCode settings
    loadConfig(): void {
        this.config = {
            enabled: workspace.getConfiguration('pathway').get('enabled', false),
            threads: workspace.getConfiguration('pathway').get('threads', []),
            logAll: workspace.getConfiguration('pathway').get('logAll', false),
            outputPath: workspace.getConfiguration('pathway').get('outputPath', '.pathway-logs')
        };

        this.activeThreads = new Set(this.config.threads);
    }

    // Runtime control
    enableThread(thread: string): void {
        this.activeThreads.add(thread);
        this.notifyListeners('enabled', thread);
    }

    disableThread(thread: string): void {
        this.activeThreads.delete(thread);
        this.notifyListeners('disabled', thread);
    }

    // Debugging helpers
    traceExecution(threads: string[], callback: () => Promise<any>): Promise<any> {
        const previous = new Set(this.activeThreads);
        threads.forEach(t => this.activeThreads.add(t));

        try {
            return await callback();
        } finally {
            this.activeThreads = previous;
        }
    }
}

