/**
 * DataOrchestrator with full pathway logging
 * @threadspec
 * threads: [DATA_INGESTION, AGENT_BRAIN]
 * expects: { repoPath: 'string' }
 * produces: { events: 'Event[]' }
 */
export class DataOrchestrator {
    async getEvents(repoPath: string): Promise<Event[]> {
        const startTime = performance.now();

        // Entry checkpoint
        logger.checkpoint(['DATA_INGESTION'], 'DataOrchestrator.getEvents.entry', {
            repoPath,
            expects: { repoPath: 'valid path' }
        });

        // Fetch from providers
        logger.checkpoint(['DATA_INGESTION'], 'DataOrchestrator.fetchProviders.start');
        const rawEvents = await this.fetchFromProviders(repoPath);
        logger.checkpoint(['DATA_INGESTION'], 'DataOrchestrator.fetchProviders.complete', {
            eventCount: rawEvents.length,
            duration: performance.now() - startTime
        });

        // Intersection with AGENT_BRAIN
        logger.checkpoint(
            ['DATA_INGESTION', 'AGENT_BRAIN'], 
            'DataOrchestrator.enrichment.start',
            { eventCount: rawEvents.length }
        );

        const enriched = await this.enrichWithAgentKnowledge(rawEvents);

        logger.checkpoint(
            ['DATA_INGESTION', 'AGENT_BRAIN'], 
            'DataOrchestrator.enrichment.complete',
            { 
                enrichedCount: enriched.length,
                addedContext: enriched.filter(e => e.context).length
            }
        );

        // Exit checkpoint
        logger.checkpoint(['DATA_INGESTION'], 'DataOrchestrator.getEvents.exit', {
            eventCount: enriched.length,
            totalDuration: performance.now() - startTime,
            produces: { events: `Event[${enriched.length}]` }
        });

        return enriched;
    }
}
